/**
 * Plans the overnight batches from the backlog. A batch is a group of features built in parallel
 * and then checked together: one CI run and one audit per batch, not per feature.
 * Plan: docs/plans/overnight-build.md. Output: docs/plans/batches.md (generated; do not edit).
 *
 * Rules:
 *  - a feature joins a batch only when everything it needs is done or in an earlier step; a need
 *    on a planned row (or a stub beyond the priority) keeps it waiting (buildableRows);
 *  - a batch holds features of one program (rust, sidecar, core, ui), so they rarely share files;
 *  - at most MAX_BATCH features per batch;
 *  - batches in the same step run side by side, each with its own CI run.
 *
 * Usage: bun scripts/overnight/plan-batches.ts [--priority 1] [--write]
 */
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { type BacklogRow, layersOf, parseBacklog } from "../issues/model.ts";

export const MAX_BATCH = 8;
const PROGRAM_ORDER = ["rust", "sidecar", "core", "ui", "cloud"] as const;

export interface Batch {
	id: string;
	step: number;
	program: string;
	features: BacklogRow[];
}

/** The program a feature belongs to: the first layer its owner names, "core" when unclear. */
export function programOf(row: BacklogRow): string {
	return layersOf(row.owner)[0] ?? "core";
}

/** Dependency depth: 0 when a feature needs nothing in the set, else one more than its deepest need. */
export function depths(rows: BacklogRow[]): Map<string, number> {
	const byId = new Map(rows.map((r) => [r.id, r]));
	const depth = new Map<string, number>();
	const visiting = new Set<string>();
	const visit = (id: string): number => {
		const known = depth.get(id);
		if (known !== undefined) return known;
		if (visiting.has(id)) throw new Error(`Dependency loop through ${id}`);
		visiting.add(id);
		const row = byId.get(id);
		const needs = (row?.needs ?? []).filter((n) => byId.has(n));
		const value = needs.length === 0 ? 0 : Math.max(...needs.map(visit)) + 1;
		visiting.delete(id);
		depth.set(id, value);
		return value;
	};
	for (const row of rows) visit(row.id);
	return depth;
}

export function planBatches(rows: BacklogRow[]): Batch[] {
	const depth = depths(rows);
	const groups = new Map<string, BacklogRow[]>();
	for (const row of rows) {
		const key = `${depth.get(row.id)}|${programOf(row)}`;
		groups.set(key, [...(groups.get(key) ?? []), row]);
	}
	const batches: Batch[] = [];
	const keys = [...groups.keys()].sort((a, b) => {
		const [da, pa] = a.split("|");
		const [db, pb] = b.split("|");
		return (
			Number(da) - Number(db) ||
			PROGRAM_ORDER.indexOf(pa as never) - PROGRAM_ORDER.indexOf(pb as never)
		);
	});
	for (const key of keys) {
		const [step, program] = key.split("|") as [string, string];
		const members = (groups.get(key) ?? []).sort(
			(a, b) => a.priority - b.priority || a.id.localeCompare(b.id),
		);
		for (let i = 0; i < members.length; i += MAX_BATCH) {
			const part = Math.floor(i / MAX_BATCH) + 1;
			const parts = Math.ceil(members.length / MAX_BATCH);
			batches.push({
				id: `s${Number(step) + 1}-${program}${parts > 1 ? `-${part}` : ""}`,
				step: Number(step) + 1,
				program,
				features: members.slice(i, i + MAX_BATCH),
			});
		}
	}
	return batches;
}

export function renderBatches(batches: Batch[], scope: string): string {
	const steps = [...new Set(batches.map((b) => b.step))];
	const lines = [
		"# Overnight batches",
		"",
		`Generated by \`bun scripts/overnight/plan-batches.ts --write\` from \`docs/plans/backlog.md\` (${scope}). Do not edit: change the backlog's priorities or Needs, then regenerate.`,
		"",
		"Batches in one step run side by side. A step starts when every batch of the step before it has merged.",
		"",
		`${batches.reduce((n, b) => n + b.features.length, 0)} features in ${batches.length} batches over ${steps.length} steps.`,
	];
	for (const step of steps) {
		lines.push("", `## Step ${step}`, "");
		for (const batch of batches.filter((b) => b.step === step)) {
			lines.push(`### ${batch.id} (${batch.program}, ${batch.features.length})`, "");
			for (const f of batch.features) lines.push(`- ${f.id} ${f.title}`);
			lines.push("");
		}
		lines.pop();
	}
	return `${lines.join("\n").trimEnd()}\n`;
}

/**
 * The stub rows up to priority `max` that can be built: everything a row needs is done, or is itself
 * buildable (so it lands in an earlier step). A need on a planned row, a stub beyond `max`, or a
 * missing row keeps the row waiting, and so does everything that needs it.
 */
export function buildableRows(all: readonly BacklogRow[], max: number): BacklogRow[] {
	const status = new Map(all.map((r) => [r.id, r.status]));
	let candidates = all.filter((r) => r.status === "stub" && r.priority <= max);
	for (;;) {
		const ids = new Set(candidates.map((r) => r.id));
		const kept = candidates.filter((r) =>
			r.needs.every((need) => status.get(need) === "done" || ids.has(need)),
		);
		if (kept.length === candidates.length) return kept;
		candidates = kept;
	}
}

if (import.meta.main) {
	const root = join(import.meta.dir, "../..");
	const at = process.argv.indexOf("--priority");
	const max = at === -1 ? 1 : Number(process.argv[at + 1]);
	const rows = buildableRows(
		parseBacklog(readFileSync(join(root, "docs/plans/backlog.md"), "utf8")),
		max,
	);
	const output = renderBatches(planBatches(rows), `priority ${max === 1 ? "1" : `1 to ${max}`}`);
	if (process.argv.includes("--write")) writeFileSync(join(root, "docs/plans/batches.md"), output);
	process.stdout.write(output);
}
